effect.shader:
// O smoothstep do AM com as pontas em qualquer ordem (o GLSL não garante o resultado com e0 > e1). Com as
// pontas iguais o AM divide por zero: ±infinito, preso em 0 ou 1 — o degrau x > e0 (a GPU do PC; no ponto
// exato ela dá NaN e o pixel some, aqui fica 0).
float degrau(float e0, float e1, float x) {
    if (e1 == e0) return x > e0 ? 1.0 : 0.0;
    float t = clamp((x - e0) / (e1 - e0), 0.0, 1.0);
    return t * t * (3.0 - 2.0 * t);
}

// UV do buffer → UV da tela, com Y para baixo (o do AM). O `acTela` devolve a UV da cena guardada de pé, a do GL
// (t = 0 EMBAIXO: é com ela que o Copiar fundo amostra o fundo), e a cena de pé (grupo solto, modelo 3D, ajuste) já
// é essa tela. Nos dois casos, inverter o t.
vec2 naTela(vec2 uv) {
    vec2 t = acEntradaDePe == 1 ? uv : acTela(uv);
    return vec2(t.x, 1.0 - t.y);
}

void main() {
    vec4 base = texture(inputImg, acScreenNorm);   // alfa reto
    vec2 tela = naTela(acScreenNorm);

    // A conta na MESMA ordem do AM (em px da tela, a matriz por fora): na borda dura (Suavização 0) um pixel
    // que cai em cima da borda vira para um lado ou o outro pelo arredondamento do float.
    vec2 st;
    if (screenSpace) {
        st = tela;
        st -= 0.5;
        st.x *= acTamanhoDaTela.x / acTamanhoDaTela.y;
    } else {
        st = ((tela * acTamanhoDaTela) - naTela(acCentroDaCamada) * acTamanhoDaTela) / length(acTamanhoDaCamada);
    }
    float a = angle * 0.0174533;
    st *= mat2(
        sin(a), -cos(a),
        cos(a), sin(a)
    );
    float p = mod(st.x * amount + phase, 1.0);
    p = degrau(width, width - smoothing, p) * degrau(0.0, smoothing, p);

    vec4 camada = vec4(base.rgb * base.a, base.a);   // pré-multiplicada, como o AM
    vec4 saida;
    if (punchout) {
        saida = camada * (1.0 - p);
    } else {
        vec4 c = vec4(color.rgb * color.a, color.a) * (p * base.a);
        saida = c + camada * (1.0 - c.a);
    }
    fragColor = saida.a > 0.0 ? vec4(saida.rgb / saida.a, saida.a) : vec4(0.0);
}
